 55	    @Transactional
 56	    public OrderShipment createOrderShipment(Order order, String receiverName, String receiverPhone,
 57	                                             String postalCode, String address) {
 58	        log.info("주문 배송 정보 생성 시작: orderId={}, receiverName={}",
 59	                order.getId(), receiverName);
 60	
 61	        OrderShipment shipment = OrderShipment.builder()
 62	                .order(order)
 63	                .receiverName(receiverName)
 64	                .receiverPhone(receiverPhone)
 65	                .postalCode(postalCode)
 66	                .address(address)
 67	                .status(ShipmentStatus.PENDING) // 초기 상태 설정
 68	                .build();
 69	
 70	        OrderShipment savedShipment = orderShipmentRepository.save(shipment);
 71	        log.info("주문 배송 정보 생성 완료: shipmentId={}, orderId={}",
 72	                savedShipment.getId(), order.getId());
 73	
 74	        return savedShipment;
 75	    }
