232	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
233	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
234	
235	        try {
236	            // 예시: 로직 단순화
237	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
238	            Document doc = Jsoup.connect(url).get();
239	            // tbody#statusDetail 의 마지막 tr => 5번째 td
240	            Elements rows = doc.select("tbody#statusDetail tr");
241	            if (rows.isEmpty()) {
242	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
243	                throw new ShipmentException(
244	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
245	                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
246	                );
247	            }
248	
249	            String status = rows.last().select("td").get(4).text();
250	            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
251	            return status;
252	
253	        } catch (Exception e) {
254	            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);
255	
256	            if (e instanceof ShipmentException) {
257	                throw e;
258	            }
259	
260	            throw new ShipmentException(
261	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
262	                    "배송 정보 조회 중 오류 발생: " + e.getMessage(),
263	                    e
264	            );
265	        }
